<?php
/* Template Name: Admin Dashboard */
if (!is_user_logged_in()) { wp_safe_redirect(home_url('/admin-login/')); exit; }
$user = wp_get_current_user();
$can_manage = current_user_can('manage_options');
if (!$can_manage && !current_user_can('edit_portfolios')) wp_die('You do not have access to this dashboard.');
$projects = get_posts(array('post_type'=>'portfolio','post_status'=>array('publish','draft','pending'),'numberposts'=>-1));
?><!doctype html><html <?php language_attributes(); ?>><head><meta charset="<?php bloginfo('charset'); ?>"><meta name="viewport" content="width=device-width, initial-scale=1"><?php wp_head(); ?></head><body class="dashboard-body"><aside class="dash-sidebar"><a class="brand" href="<?php echo esc_url(home_url('/')); ?>"><span class="brand-mark">T</span><span>Tech<span class="brand-accent">Solutions</span></span></a><p class="side-label">WORKSPACE</p><a class="side-link selected" href="<?php echo esc_url(home_url('/dashboard/')); ?>">▦ &nbsp; Overview</a><a class="side-link" href="#projects">▤ &nbsp; All Projects</a><a class="side-link" href="#add-project">＋ &nbsp; Add Project</a><p class="side-label">ACCOUNT</p><a class="side-link" href="<?php echo esc_url(home_url('/')); ?>">↗ &nbsp; View Website</a><a class="side-link" href="<?php echo esc_url(wp_logout_url(home_url('/admin-login/'))); ?>">⇥ &nbsp; Logout</a></aside><main class="dash-main"><div class="dash-top"><div><span class="eyebrow">WORKSPACE / OVERVIEW</span><h1>Dashboard</h1></div><div class="user-chip"><?php echo get_avatar($user->ID, 34); ?><span><?php echo esc_html($user->display_name); ?><small><?php echo $can_manage ? 'Administrator' : 'Portfolio Editor'; ?></small></span></div></div>
<?php if (isset($_GET['saved'])): ?><div class="success-msg">Project saved successfully.</div><?php endif; ?>
<div class="stats-grid"><div class="stat-card"><span>Total Projects</span><strong><?php echo count($projects); ?></strong></div><div class="stat-card"><span>Published</span><strong><?php echo count(array_filter($projects, function($p){return $p->post_status==='publish';})); ?></strong></div><div class="stat-card"><span>Drafts</span><strong><?php echo count(array_filter($projects, function($p){return $p->post_status==='draft';})); ?></strong></div></div>
<section class="dash-panel" id="projects"><div class="panel-heading"><h2>Portfolio Projects</h2><a class="primary-btn small-btn" href="#add-project">＋ Add Project</a></div><div class="table-wrap"><table><thead><tr><th>Project</th><th>Status</th><th>Last Updated</th><th>Action</th></tr></thead><tbody><?php if ($projects): foreach ($projects as $project): ?><tr><td><strong><?php echo esc_html($project->post_title); ?></strong></td><td><span class="status <?php echo esc_attr($project->post_status); ?>"><?php echo esc_html(ucfirst($project->post_status)); ?></span></td><td><?php echo esc_html(get_the_modified_date('', $project)); ?></td><td><a href="#add-project" onclick="document.getElementById('project_id').value='<?php echo esc_js($project->ID); ?>';document.getElementById('project_title').value='<?php echo esc_js($project->post_title); ?>';document.getElementById('project_description').value='<?php echo esc_js($project->post_content); ?>';">Edit</a><?php if ($can_manage): ?> · <a class="delete-link" href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=digisolutions_delete_project&project_id='.$project->ID), 'digisolutions_delete_'.$project->ID)); ?>" onclick="return confirm('Move this project to trash?')">Delete</a><?php endif; ?></td></tr><?php endforeach; else: ?><tr><td colspan="4">No projects yet. Add your first project below.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="dash-panel" id="add-project"><h2>Add / Edit Project</h2><form class="project-form" method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" enctype="multipart/form-data"><?php wp_nonce_field('digisolutions_save_project', 'digisolutions_project_nonce'); ?><input type="hidden" name="action" value="digisolutions_save_project"><input type="hidden" name="project_id" id="project_id" value=""><label>Project Title<input id="project_title" name="project_title" required></label><label>Project Description<textarea id="project_description" name="project_description" rows="5"></textarea></label><label>Featured Image<input type="file" name="project_image" accept="image/*"></label><button class="primary-btn" type="submit">Save Project →</button><p class="form-note">Editors save projects as drafts. Administrators can publish them.</p></form></section></main><?php wp_footer(); ?></body></html>
